'use strict';

// The vulnerable implementation: the whole module IS the callable, and it
// is ANONYMOUS. There is therefore no function named "dangerousOp"
// anywhere in this package except the stale fallback in index.js -- which
// is exactly what makes that fallback the only thing a name-based export
// attribution can find.
module.exports = function (input) {
  return 'danger:' + String(input);
};
